INSERT INTO `broadcasts` VALUES (7,'Libur Natal dan Tahun Baru 2025/2026','Berdasarkan keputusan menteri dengan no 12345 bahwa tanggal 26 desember 2025 sampai dengan 30 desember 2025 merupakan cuti nasional, cuti tidak memotong cuti karyawan , untuk yang bertugas di lapangan tetap hadir sesuai dengan jadwal piket yang telah di tentukan\n\nterimakasih','all','[]','[]','medium',21,'tes_mdl','sent','2025-12-18 02:16:55','2025-12-18 09:35:20','MDL'),(8,'Hari Libur Nasional','Berdasarkan keputusan menteri keuangan bahwa tanggal 1 januari 2026 adalah hari libur nasional, dan tidak di potong cuti tahunan\n\nterimakasih','all',NULL,NULL,'low',2,'tes_mdl','sent','2025-12-18 02:34:28','2025-12-18 02:34:28','MDL'),(9,'TESTING','LAGI TESTING SEKALI LAGI BUAT NOTIF KE EMPLOYEE','all',NULL,NULL,'medium',2,'tes_mdl','sent','2025-12-18 03:09:15','2025-12-18 03:09:15','MDL'),(10,'mau test','test broadcast \nmau kasih tau sudah bisa berjalan dengan baik\nsehingga bisa di live\n\nterimakasih','all',NULL,NULL,'medium',2,'Super Administrator','sent','2025-12-18 21:52:31','2025-12-18 21:52:31','MDL');
